"""AGENT-WORLD: не торговать по RSS-новостям старше max_news_age_hours."""
from __future__ import annotations

from datetime import datetime, timedelta, timezone

from telegram_agent.world_feed import (
    is_news_too_stale_for_trade,
    news_age_hours,
    parse_event_published_utc,
)


def test_parse_event_published_utc_rfc2822():
    event = {"published_hint": "Thu, 15 May 2026 10:30:00 GMT"}
    pub = parse_event_published_utc(event)
    assert pub is not None
    assert pub.year == 2026
    assert pub.month == 5
    assert pub.day == 15


def test_parse_event_published_utc_iso():
    event = {"published_hint": "2026-06-28T04:22:27+00:00"}
    pub = parse_event_published_utc(event)
    assert pub is not None
    assert pub.hour == 4


def test_news_age_hours_fresh():
    now = datetime(2026, 6, 28, 10, 0, tzinfo=timezone.utc)
    event = {"published_hint": "2026-06-28T08:00:00+00:00"}
    assert news_age_hours(event, now=now) == 2.0


def test_is_news_too_stale_blocks_old_article():
    now = datetime(2026, 6, 28, 10, 0, tzinfo=timezone.utc)
    event = {
        "published_hint": "Thu, 15 May 2026 12:00:00 GMT",
        "title": "Thorchain exploit",
    }
    stale, reason = is_news_too_stale_for_trade(event, 5.0, now=now)
    assert stale is True
    assert "устарела" in reason


def test_is_news_too_stale_allows_recent():
    now = datetime(2026, 6, 28, 10, 0, tzinfo=timezone.utc)
    event = {"published_hint": (now - timedelta(hours=3)).isoformat()}
    stale, reason = is_news_too_stale_for_trade(event, 5.0, now=now)
    assert stale is False
    assert reason == ""


def test_is_news_too_stale_disabled_when_max_zero():
    now = datetime(2026, 6, 28, 10, 0, tzinfo=timezone.utc)
    event = {"published_hint": "Thu, 01 Jan 2020 00:00:00 GMT"}
    stale, _ = is_news_too_stale_for_trade(event, 0.0, now=now)
    assert stale is False


def test_is_news_too_stale_blocks_unparseable_date():
    now = datetime(2026, 6, 28, 10, 0, tzinfo=timezone.utc)
    event = {"published_hint": "not-a-date", "title": "x"}
    stale, reason = is_news_too_stale_for_trade(event, 5.0, now=now)
    assert stale is True
    assert "не удалось определить дату" in reason

#!/usr/bin/env python3
"""Analyze AGENT-WORLD losing trades by source (last 3 days from Jun 28 2026)."""
from __future__ import annotations

import json
import re
import sys
from collections import Counter, defaultdict
from datetime import datetime, timezone
from pathlib import Path

BASE = Path(__file__).resolve().parent
CUTOFF = datetime(2026, 6, 25, 0, 0, 0, tzinfo=timezone.utc)

CLOSED_PAT = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}),\d+ \[INFO\] prd_agent\.trades: CLOSED (\w+): pnl=\$(-?[\d.]+)"
)


def parse_ts(s: str) -> datetime:
    return datetime.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)


def load_jsonl(path: Path) -> list[dict]:
    if not path.exists():
        return []
    out = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            pass
    return out


def bucket_source(raw: str) -> str:
    s = (raw or "").upper()
    if "AGENT-WORLD" in s or "AGENT_WORLD" in s:
        return "rss"
    if "SPIKE" in s or "MARKET_SCANNER" in s or s == "SCANNER":
        return "scanner"
    if "OWN_MULTI" in s or s == "OWN_MULTI_AGENT":
        return "own_multi_agent"
    if "TA_VOLATILITY" in s:
        return "ta_volatility"
    if "TELEGRAM" in s:
        return "telegram_channel"
    return "own_multi_agent_or_unknown"


def main() -> int:
    losers = []
    for line in (BASE / "bot.log").read_text(encoding="utf-8", errors="replace").splitlines():
        m = CLOSED_PAT.match(line)
        if not m:
            continue
        ts = parse_ts(m.group(1))
        if ts < CUTOFF:
            continue
        pnl = float(m.group(3))
        if pnl < 0:
            losers.append({"ts": ts, "symbol": m.group(2), "pnl": pnl})

    entries: list[dict] = []
    for path, default in [
        (BASE / "reports/telegram_signals/signals.jsonl", None),
        (BASE / "reports/telegram_signals/market_scanner.jsonl", "MARKET_SCANNER"),
    ]:
        for row in load_jsonl(path):
            action = str(row.get("action", ""))
            ok = action in ("executed", "scanner_executed")
            if not ok:
                res = row.get("execution_result") if isinstance(row.get("execution_result"), dict) else {}
                ok = bool(res.get("success"))
            if not ok:
                continue
            sig = row.get("signal") if isinstance(row.get("signal"), dict) else {}
            src = str(sig.get("source") or default or "")
            sym = str(sig.get("symbol", "")).upper()
            raw_t = sig.get("received_at_utc") or sig.get("message_time_utc") or ""
            try:
                t = datetime.fromisoformat(str(raw_t).replace("Z", "+00:00"))
            except (TypeError, ValueError):
                continue
            if t.tzinfo is None:
                t = t.replace(tzinfo=timezone.utc)
            if t < CUTOFF:
                continue
            entries.append(
                {
                    "ts": t,
                    "symbol": sym,
                    "source": src,
                    "bucket": bucket_source(src),
                    "side": str(sig.get("side", "")).upper(),
                }
            )

    # bot.log: explicit source mentions near fills
    for line in (BASE / "bot.log").read_text(encoding="utf-8", errors="replace").splitlines():
        if not line.startswith("2026-06-2"):
            continue
        ts_m = re.match(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})", line)
        if not ts_m:
            continue
        ts = parse_ts(ts_m.group(1))
        if ts < CUTOFF:
            continue
        sym_m = re.search(r"(\w+USDT)", line)
        if not sym_m:
            continue
        sym = sym_m.group(1)
        if "own_multi_agent" in line and ("Leverage" in line or "signal_received" in line or "OPEN" in line):
            entries.append({"ts": ts, "symbol": sym, "source": "own_multi_agent", "bucket": "own_multi_agent", "side": ""})
        if "AGENT-WORLD" in line and ("executed" in line.lower() or "ИСПОЛНЕНО" in line):
            entries.append({"ts": ts, "symbol": sym, "source": "AGENT-WORLD", "bucket": "rss", "side": ""})
        if "SPIKE_SCANNER" in line or "scanner_executed" in line or "MARKET_SCANNER" in line:
            entries.append({"ts": ts, "symbol": sym, "source": "scanner", "bucket": "scanner", "side": ""})

    def match_bucket(sym: str, close_ts: datetime) -> str:
        best = None
        for e in entries:
            if e["symbol"] != sym:
                continue
            dt = (close_ts - e["ts"]).total_seconds()
            if -3600 <= dt <= 96 * 3600:
                if best is None or e["ts"] > best["ts"]:
                    best = e
        return best["bucket"] if best else "own_multi_agent_or_unknown"

    bucket_pnl: dict[str, float] = defaultdict(float)
    bucket_cnt: Counter[str] = Counter()
    details: dict[str, list[tuple]] = defaultdict(list)

    for L in losers:
        b = match_bucket(L["symbol"], L["ts"])
        bucket_pnl[b] += L["pnl"]
        bucket_cnt[b] += 1
        if L["pnl"] <= -0.3:
            details[b].append((L["ts"].strftime("%m-%d %H:%M"), L["symbol"], L["pnl"]))

    total = sum(x["pnl"] for x in losers)
    print(f"PERIOD: {CUTOFF.date()} .. 2026-06-28 (UTC log timestamps)")
    print(f"LOSING CLOSES: {len(losers)} | TOTAL PnL: ${total:.2f}")
    print()
    order = sorted(bucket_pnl.keys(), key=lambda k: bucket_pnl[k])
    for k in order:
        print(f"  {k}: {bucket_cnt[k]} trades | sum ${bucket_pnl[k]:.2f} | avg ${bucket_pnl[k]/bucket_cnt[k]:.2f}")
    print()
    print("TOP LOSSES (>= $0.30) BY SOURCE:")
    for k in order:
        rows = sorted(details[k], key=lambda x: x[2])[:10]
        if not rows:
            continue
        print(f"  [{k}]")
        for r in rows:
            print(f"    {r[0]} {r[1]} ${r[2]:.2f}")

    # RSS-specific from signals.jsonl executed in period with later loss
    rss_exec = [e for e in entries if e["bucket"] == "rss"]
    print()
    print(f"RSS EXECUTIONS in period (signals.jsonl): {len(rss_exec)}")
    rss_syms = {e["symbol"] for e in rss_exec}
    rss_loss = [L for L in losers if L["symbol"] in rss_syms]
    print(f"RSS-related symbols that later closed negative: {len(rss_loss)} | ${sum(x['pnl'] for x in rss_loss):.2f}")

  scanner_exec = [e for e in entries if e["bucket"] == "scanner"]
    print(f"SCANNER EXECUTIONS in period: {len(scanner_exec)}")
    sc_syms = {e["symbol"] for e in scanner_exec}
    sc_loss = [L for L in losers if L["symbol"] in sc_syms]
    print(f"Scanner-related symbols closed negative: {len(sc_loss)} | ${sum(x['pnl'] for x in sc_loss):.2f}")

    return 0


if __name__ == "__main__":
