#!/usr/bin/env python3
"""Losing trades by entry source from trade_history.jsonl (last 3 days)."""
from __future__ import annotations

import json
from collections import Counter, defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

BASE = Path(__file__).resolve().parent
JOURNAL = BASE / "data" / "trades" / "trade_history.jsonl"
TZ3 = timezone(timedelta(hours=3))
# 3 days back from Jun 28 2026 UTC+3 end of day
END = datetime(2026, 6, 28, 23, 59, 59, tzinfo=TZ3)
START = END - timedelta(days=3)


def classify_source(raw: str) -> str:
    s = (raw or "").strip().lower()
    if not s:
        return "unknown"
    if "agent-world" in s or "agent_world" in s:
        return "rss"
    if "market_scanner" in s or "spike" in s or s == "scanner":
        return "scanner"
    if "own_multi" in s:
        return "own_multi_agent"
    if "ta_volatility" in s:
        return "ta_volatility"
    if "telegram" in s:
        return "telegram_channel"
    return s


def parse_ts(raw: str) -> datetime | None:
    try:
        t = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if t.tzinfo is None:
        t = t.replace(tzinfo=timezone.utc)
    return t


def main() -> None:
    rows = []
    for line in JOURNAL.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line.strip():
            continue
        try:
            rows.append(json.loads(line))
        except json.JSONDecodeError:
            pass

    # Stack open entries per symbol: order_id -> source
    open_by_oid: dict[str, dict] = {}
    open_stack: dict[str, list[dict]] = defaultdict(list)

    losers: list[dict] = []

    for row in rows:
        ev = str(row.get("event", "")).lower()
        sym = str(row.get("symbol", "")).upper()
        ts = parse_ts(row.get("ts", ""))
        if not sym or not ts:
            continue

        if ev == "entered":
            src = str(row.get("source") or row.get("grade") or "")
            entry = {
                "symbol": sym,
                "source": src,
                "bucket": classify_source(src),
                "ts": ts,
                "order_id": str(row.get("order_id", "")),
                "side": str(row.get("side", "")),
            }
            oid = entry["order_id"]
            if oid:
                open_by_oid[oid] = entry
            open_stack[sym].append(entry)

        elif ev == "closed":
            pnl = float(row.get("pnl") or 0)
            if pnl >= 0:
                continue
            ts_local = ts.astimezone(TZ3)
            if ts_local < START or ts_local > END:
                continue

            oid = str(row.get("order_id", ""))
            matched = open_by_oid.get(oid)
            if not matched and open_stack.get(sym):
                matched = open_stack[sym][-1]

            src_raw = matched["source"] if matched else str(row.get("source") or "")
            bucket = classify_source(src_raw) if matched else classify_source(str(row.get("source") or ""))
            if bucket == "unknown" and str(row.get("origin", "")).lower() == "manual":
                bucket = "manual"

            losers.append(
                {
                    "ts": ts_local,
                    "symbol": sym,
                    "pnl": pnl,
                    "side": str(row.get("side", "")),
                    "reason": str(row.get("reason", "")),
                    "source_raw": src_raw or "?",
                    "bucket": bucket,
                    "order_id": oid[:8] if oid else "",
                }
            )
            # pop stack on close
            if sym in open_stack and open_stack[sym]:
                if matched and matched in open_stack[sym]:
                    open_stack[sym].remove(matched)
                elif open_stack[sym]:
                    open_stack[sym].pop()

    total = sum(x["pnl"] for x in losers)
    print(f"AGENT-WORLD: убыточные закрытия {START.date()} — {END.date()} (UTC+3)")
    print(f"Всего минусовых: {len(losers)} | Сумма: ${total:.2f} USDT")
    print()

    by_bucket: dict[str, list] = defaultdict(list)
    for L in losers:
        by_bucket[L["bucket"]].append(L)

    for bucket in ("rss", "scanner", "own_multi_agent", "ta_volatility", "telegram_channel", "manual", "unknown"):
        items = by_bucket.get(bucket, [])
        if not items:
            continue
        s = sum(x["pnl"] for x in items)
        print(f"## {bucket.upper()}: {len(items)} сделок | ${s:.2f}")
        for x in sorted(items, key=lambda r: r["pnl"])[:15]:
            print(
                f"  {x['ts'].strftime('%d.%m %H:%M')} {x['symbol']:<14} "
                f"${x['pnl']:>7.2f}  {x['side']:<4}  src={x['source_raw'][:40]}"
            )
        if len(items) > 15:
            print(f"  ... ещё {len(items)-15}")
        print()

    # Summary table
    print("--- СВОДКА ---")
    for bucket in sorted(by_bucket, key=lambda b: sum(x["pnl"] for x in by_bucket[b])):
        items = by_bucket[bucket]
        print(
            f"{bucket:20} {len(items):3} trades  ${sum(x['pnl'] for x in items):8.2f}  "
            f"avg ${sum(x['pnl'] for x in items)/len(items):.2f}"
        )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Full bot.log attribution: losing closes Jun 25-28 by RSS / scanner / own_multi_agent."""
from __future__ import annotations

import json
import re
from collections import defaultdict
from datetime import datetime, timedelta
from pathlib import Path

BASE = Path(__file__).resolve().parent
LOG = BASE / "bot.log"
BTL = BASE / "data" / "bot_trade_log.jsonl"

START = datetime(2026, 6, 25)
END = datetime(2026, 6, 28, 23, 59, 59)

ENTERED_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}),\d+ \[INFO\] prd_agent\.trades: ENTERED (\w+): \w+ \[(\w+)\]"
)
CLOSED_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}),\d+ \[INFO\] prd_agent\.trades: CLOSED (\w+): pnl=\$(-?[\d.]+)"
)
ADOPTED_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}),\d+ \[INFO\] prd_agent\.positions: Adopted position (\w+) \w+ origin=(\w+)"
)
TS_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})")


def parse_ts(s: str) -> datetime:
    return datetime.strptime(s, "%Y-%m-%d %H:%M:%S")


def norm_source(raw: str) -> str:
    s = (raw or "").lower()
    if s in ("agent_world", "agent-world"):
        return "rss"
    if s in ("own_multi_agent", "orchestrator"):
        return "own_multi_agent"
    if "market_scanner" in s or s == "scanner":
        return "scanner"
    if "spike" in s:
        return "scanner"  # spike_scalp -> scanner family
    if s == "rss":
        return "rss"
    return "unknown"


def classify_tg_line(line: str, sym: str) -> str | None:
    if sym not in line:
        return None
    low = line.lower()
    if "spike" in low and ("exec" in low or "setup" in low or "notified" in low):
        return "scanner"
    if "market scanner" in low or "scanner_bos" in low or "market_scan" in low:
        return "scanner"
    if "agent-world" in low or "agent_world" in low or "rss" in low:
        return "rss"
    return None


def main() -> None:
    # preload bot_trade_log opens
    btl_opens: list[tuple[datetime, str, str]] = []
    if BTL.exists():
        for line in BTL.read_text(encoding="utf-8", errors="replace").splitlines():
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                continue
            ts = datetime.fromisoformat(str(row["opened_at_utc"]).replace("Z", "+00:00")).replace(tzinfo=None)
            btl_opens.append((ts, str(row["symbol"]).upper(), norm_source(str(row.get("source", "")))))

    stacks: dict[str, list[tuple[datetime, str]]] = defaultdict(list)
    recent_tg: list[tuple[datetime, str]] = []
    losers: list[dict] = []

    for line in LOG.read_text(encoding="utf-8", errors="replace").splitlines():
        ts_m = TS_RE.match(line)
        if not ts_m:
            continue
        ts = parse_ts(ts_m.group(1))

        if "TG_AGENT:" in line:
            recent_tg.append((ts, line))
            recent_tg = [(t, l) for t, l in recent_tg if (ts - t).total_seconds() <= 180]

        m = ENTERED_RE.match(line)
        if m:
            sym, src = m.group(2), norm_source(m.group(3))
            stacks[sym].append((ts, src))
            continue

        m = ADOPTED_RE.match(line)
        if m:
            sym = m.group(2)
            origin = m.group(3)
            src = "unknown"
            for t, tg in reversed(recent_tg):
                if sym not in tg:
                    continue
                hint = classify_tg_line(tg, sym)
                if hint:
                    src = hint
                    break
            if src == "unknown" and origin == "bot":
                # match bot_trade_log nearest open
                cand = [x for x in btl_opens if x[1] == sym and abs((ts - x[0]).total_seconds()) < 600]
                if cand:
                    src = min(cand, key=lambda x: abs((ts - x[0]).total_seconds()))[2]
                else:
                    src = "scanner"  # most adopted bot positions are scanner/TG exec
            elif src == "unknown" and origin == "manual":
                # manual adopt after scanner trigger still scanner
                for t, tg in reversed(recent_tg):
                    if sym in tg and classify_tg_line(tg, sym):
                        src = classify_tg_line(tg, sym) or "unknown"
                        break
            stacks[sym].append((ts, src))
            continue

        m = CLOSED_RE.match(line)
        if not m:
            continue
        sym = m.group(2)
        pnl = float(m.group(3))
        if pnl >= 0 or ts < START or ts > END:
            continue

        src = "unknown"
        if stacks.get(sym):
            _, src = stacks[sym].pop()
        else:
            # fallback bot_trade_log before close
            cand = [x for x in btl_opens if x[1] == sym and x[0] <= ts]
            if cand:
                src = max(cand, key=lambda x: x[0])[2]

        losers.append({"ts": ts, "symbol": sym, "pnl": pnl, "source": src})

    by_src: dict[str, list] = defaultdict(list)
    for L in losers:
        by_src[L["source"]].append(L)

    total = sum(x["pnl"] for x in losers)
    print("AGENT-WORLD: убыточные закрытия 25–28.06.2026 (время в bot.log, UTC)")
    print(f"Всего: {len(losers)} сделок | Сумма: ${total:.2f} USDT\n")

    labels = {
        "scanner": "SCANNER (MARKET_SCANNER + BOS + spike)",
        "rss": "RSS (AGENT-WORLD / agent_world)",
        "own_multi_agent": "OWN_MULTI_AGENT (оркестратор TA)",
        "unknown": "НЕ ОПРЕДЕЛЁН (старый вход / ручное)",
    }
    order = ["scanner", "rss", "own_multi_agent", "unknown"]
    for key in order:
        items = by_src.get(key, [])
        if not items:
            print(f"## {labels[key]}: 0 сделок | $0.00\n")
            continue
        s = sum(x["pnl"] for x in items)
        print(f"## {labels[key]}: {len(items)} сделок | ${s:.2f} | средний ${s/len(items):.2f}")
        for x in sorted(items, key=lambda r: r["pnl"])[:12]:
            print(f"   {x['ts'].strftime('%d.%m %H:%M')} {x['symbol']:<14} ${x['pnl']:>7.2f}")
        if len(items) > 12:
            print(f"   ... ещё {len(items)-12} сделок")
        print()

    print("--- СВОДКА ---")
    for key in order:
        items = by_src.get(key, [])
        if items:
            print(f"{labels[key]:45} {len(items):3}  ${sum(x['pnl'] for x in items):8.2f}")


if __name__ == "__main__":
    main()

