            sym,
            pos_side,
            sig.side,
        )

async def _close_on_reverse_signal(self, sig: UnifiedSignal, pos_row: Dict) -> None:
    sym = sig.symbol.upper()
    pos_side = str(pos_row.get("side", "") or "")
    qty = self._position_size(pos_row)
    pidx = int(pos_row.get("positionIdx", 0) or 0)
    reason = f"обратный сигнал {normalize_trade_side(sig.side)} — срочное закрытие"
    logger.warning(
        "REVERSE CLOSE %s: open=%s signal=%s conf=%.0f%% src=%s",
        sym,
        pos_side,
        sig.side,
        float(sig.confidence or 0) * 100 if float(sig.confidence or 0) <= 1 else float(sig.confidence),
        sig.source,
    )
    if not hasattr(self.exchange, "close_position"):
        logger.error("REVERSE CLOSE %s: exchange.close_position unavailable", sym)
        return
    res = await self.exchange.close_position(
        sym, pos_side, qty=qty if qty > 0 else None, position_idx=pidx
    )
    if res.get("success") or res.get("orderId"):
        msg = (
            f"🔄 <b>Обратный сигнал — закрыто</b>\n"
            f"{sym}: было {pos_side} → сигнал {sig.side}\n"
            f"Источник: {sig.source}"
